import json
from pathlib import Path
G = Path(__file__).resolve().parent
layouts = json.loads((G.parent / 'hero_exp1/sprite_prompts.json').read_text(encoding='utf-8'))['layouts']
H = {}


def add(code, name, ut, layout, desc, back, side, forbid, verify, mounted=False):
    d = {'name': name, 'unit_type': ut, 'layout': layout, 'desc': desc, 'back': back, 'side': side, 'forbid': forbid, 'verify': verify}
    if mounted:
        d['mounted'] = True
    H[code] = d


